import pandas as pd
import numpy as np

# Load the data
no2_data = pd.read_csv('chunks_csv/outlierr/2023_no2.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Create a dictionary to store the neighbors for each borough
neighbors = {}
for index, row in adjacency_data.iterrows():
    if row['borough'] not in neighbors:
        neighbors[row['borough']] = []
    neighbors[row['borough']].append(row['neighbor'])

# Create a dictionary to store the NO2 values for each borough
no2_values = no2_data.set_index('borough')['NO2_value'].to_dict()

# Create a spatial weights matrix
weights = {}
for borough, neighbors_list in neighbors.items():
    weights[borough] = {}
    for neighbor in neighbors_list:
        weights[borough][neighbor] = 1
    weights[borough][borough] = 0  # self-weight is 0

# Compute the spatial lag of NO2 values
spatial_lag = {}
for borough, neighbors_list in neighbors.items():
    spatial_lag[borough] = np.mean([no2_values[neighbor] for neighbor in neighbors_list])

# Compute the residuals
residuals = {}
for borough, no2_value in no2_values.items():
    residuals[borough] = no2_value - spatial_lag[borough]

# Compute the Moran's I statistic
moran_i = 0
for borough, residual in residuals.items():
    moran_i += residual * spatial_lag[borough]

# Account for masking bias
expected_residuals = {}
for borough, residual in residuals.items():
    neighbors_residuals = [residuals[neighbor] for neighbor in neighbors[borough]]
    expected_residuals[borough] = np.mean(neighbors_residuals)

# Compute the z-score for Kingston upon Thames
kingston_residual = residuals['Kingston upon Thames']
kingston_expected_residual = expected_residuals['Kingston upon Thames']
z_score = (kingston_residual - kingston_expected_residual) / np.std([residual - expected_residual for residual, expected_residual in zip(residuals.values(), expected_residuals.values())])

# Determine if Kingston upon Thames is a spatial outlier
if z_score > 2:
    verdict = 'OUTLIER - HIGH'
elif z_score < -2:
    verdict = 'OUTLIER - LOW'
else:
    verdict = 'NOT AN OUTLIER'

print(f'data_points_used = {len(no2_values)}')
print(f'FINAL ANSWER: {verdict} (z = {z_score})')

# The computed real number used:
print(z_score)
